    /*
     * Assign a Metric
     * 
     * @param	parentId	UUID
     * @param	assignment 	Metric 
     * @return	Alert
     */
    public Alert assignMetric( UUID parentId, Metric assignment ) {
	    LOGGER.info("assigning Metric as " + assignment.toString() );

	    Alert parentEntity = repository.findById( parentId ).get();
	    assignment = registry.project( Metric.class, assignment.getMetricId());

	    // ------------------------------------------
		// assign the Metric to the parent entity
		// ------------------------------------------ 
	    parentEntity.setMetric( assignment );

	    // ------------------------------------------
    	// save the parent entity
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

