    /*
     * Add to the Anomalies
     * 
     * @param	parentID	UUID
     * @param	addTo		childType
     * @return	Alert
     */
    public Alert addToAnomalies( UUID parentId, Anomaly addTo ) {
	    LOGGER.info("handling AssignAnomaliesToAlertEvent - " );
	    
	    Alert parentEntity = repository.findById(parentId).get();
	    Anomaly child = registry.project( Anomaly.class, addTo.getAnomalyId());
	    
	    parentEntity.getAnomalies().add( child );

	    // ------------------------------------------
    	// save 
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

    /*
     * Remove from the Anomalies
     * 
     * @param	parentID	UUID
     * @param	removeFrom	childType
     * @return	Alert
     */
	public Alert removeFromAnomalies( UUID parentId, Anomaly removeFrom ) {
	    LOGGER.info("handling RemoveAnomaliesFromAlertEvent " );
	
	    Alert parentEntity = repository.findById(parentId).get();
	    Anomaly child = registry.project( Anomaly.class, removeFrom.getAnomalyId());
	    
	    parentEntity.getAnomalies().remove( child );
	
	    // ------------------------------------------
		// save
		// ------------------------------------------ 
	    update(parentEntity);
	    
	    return parentEntity;
	}

